// Flatten what the shop did into one document per fact, written so Cognee's extraction can
// rebuild the relationships: every sentence names the actors (action, customers, amounts, dates)
// rather than pointing at ids. Graph quality is decided here, not at query time.
const actions = $('Fetch actions').first()?.json?.actions ?? [];
const insights = $('Fetch insights').first()?.json?.insights ?? [];

const docs = [];

for (const action of actions) {
  if (action.status !== 'executed') continue;
  const outcomes = (action.outcomes ?? [])
    .map((o) => `${o.metric} = ${o.value?.display ?? o.value_num ?? ''}`.trim())
    .filter(Boolean)
    .join('; ');
  docs.push({
    id: action.id,
    kind: 'action',
    text: [
      `Action ${action.id} (${action.tool_name}) was approved and executed on ${action.executed_at}.`,
      action.summary_en,
      `It reached ${action.target_count} customers.`,
      outcomes ? `Measured outcome: ${outcomes}.` : 'No outcome measured yet.',
    ].filter(Boolean).join(' '),
  });
}

for (const insight of insights) {
  docs.push({
    id: insight.id,
    kind: 'insight',
    text: `Finding (${insight.kind}, ${insight.severity}): ${insight.title_en}. ${insight.body_en} Estimated impact ${insight.impact?.display ?? ''}.`,
  });
}

// Returning no items stops the branch, which is exactly right: an empty sync must not POST an
// empty batch to Cognee and then fail the read-back assertion for the wrong reason.
return docs.map((doc) => ({ json: doc }));

// A read-back assertion, not decoration. A memory layer that quietly stops remembering is worse
// than one that is obviously down: the next conversation would lose its history and nobody would
// find out until MunshiJi asked a customer something it had already been told.
function count(payload) {
  if (Array.isArray(payload)) return payload.length;
  if (payload && typeof payload === 'object') {
    for (const key of ['results', 'data', 'items', 'search_results', 'search_result', 'searchResult', 'documents', 'answers', 'graphs']) {
      if (Array.isArray(payload[key])) return payload[key].length;
    }
  }
  if (typeof payload === 'string') return payload.trim() ? 1 : 0;
  return 0;
}

const body = $json ?? {};
const hits = count(body);
const dataset = 'munshiji_' + ($vars.MUNSHIJI_MERCHANT_ID || 'default');

if (hits === 0) {
  throw new Error(`Cognee returned no results after cognify - the graph did not build for ${dataset}`);
}

return [{
  json: {
    ok: true,
    synced_at: new Date().toISOString(),
    dataset,
    documents: $('Build documents').all().length,
    hits,
    sample: body,
  },
}];
